19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Computes the SHA-256 digest of a string as a lower-case hex string. Kept apart from
25	 * {@link OwnerRestControllerV1} so the request handler stays focused on orchestration, and so the
26	 * single piece of SHA-256 boilerplate lives in one place: the several owner values that are derived
27	 * by hashing (such as the {@link HouseholdNormalizer#householdId household identifier}) share this
28	 * one helper rather than each repeating the digest-and-hex-encode dance.
29	 */
30	final class Sha256 {
31	
32	    private Sha256() {
33	    }
34	
35	    /**
36	     * Returns the SHA-256 digest of the UTF-8 bytes of {@code input} as a 64-character lower-case
37	     * hex string. Callers that need a shorter, opaque token take a prefix of the result.
38	     *
39	     * @param input the string to hash
40	     * @return the digest as 64 lower-case hex characters
41	     */
42	    static String hex(String input) {
43	        try {
44	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                sb.append(String.format("%02x", b));
48	            }
49	            return sb.toString();
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            // SHA-256 is a required algorithm on every JVM, so this cannot happen.
53	            throw new IllegalStateException("SHA-256 is not available", ex);
54	        }
55	    }
56	
57	}
