17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
33	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
36	import org.springframework.samples.petclinic.mapper.MembershipLevel;
37	import org.springframework.samples.petclinic.mapper.OwnerLocality;
38	import org.springframework.samples.petclinic.mapper.OwnerMapper;
39	import org.springframework.samples.petclinic.mapper.PetMapper;
40	import org.springframework.samples.petclinic.mapper.VisitMapper;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.util.StringUtils;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
72	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
73	     * addresses are lower-cased before being stored.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
77	
78	    /** An owner's postcode, when supplied, must be exactly four digits. */
79	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
80	
81	    /**
82	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
83	     * named logger keeps them addressable independently of the class's diagnostic logging.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Maximum number of owners a single city may contain. A create that would take the owner's city
89	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
90	     */
91	    private static final int CITY_OWNER_LIMIT = 50;
92	
93	    /**
94	     * Maximum number of owners that may be registered on a single day. A create that would take the
95	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
96	     * have already been created that day - is rejected with a 429.
97	     */
98	    private static final int DAILY_OWNER_LIMIT = 100;
99	
100	    /**
101	     * Number of owners that must already have been created for a given day before the create
102	     * response flags a bulk sign-up. When more than this many owners already share a
103	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
104	     */
105	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
106	
107	    private final ClinicService clinicService;
108	
109	    private final OwnerMapper ownerMapper;
110	
111	    private final PetMapper petMapper;
112	
113	    private final VisitMapper visitMapper;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
149	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
154	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
155	     * owner sign-ups.
156	     *
157	     * @param registrationDate the day to inspect, or {@code null}
158	     * @return {@code true} when more than the threshold of owners are registered on that day
159	     */
160	    private boolean isBulkSignupDay(LocalDate registrationDate) {
161	        return registrationDate != null
162	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
169	        validateRequiredFields(ownerFieldsDto);
170	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(normalizeEmail(owner.getEmail()));
175	        if (owner.getRegistrationDate() == null) {
176	            owner.setRegistrationDate(LocalDate.now());
177	        }
178	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
179	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
180	        owner.setIdentityKey(buildIdentityKey(owner,
181	            Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())));
182	        rejectDuplicateOwner(owner.getIdentityKey());
183	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
184	            throw new OwnerCityFullException(owner.getCity());
185	        }
186	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
187	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
188	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
189	        }
190	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
191	        owner.setCustomerCode(buildCustomerCode(owner));
192	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
193	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
194	        this.clinicService.saveOwner(owner);
195	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
197	            MembershipLevel.forOwner(owner));
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
200	        headers.setLocation(UriComponentsBuilder.newInstance()
201	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
202	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    /**
206	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
207	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
208	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
209	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
210	     * after normalization is still rejected.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields
213	     */
214	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
215	        List<String> missingFields = new ArrayList<>();
216	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
217	            missingFields.add("firstName");
218	        }
219	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
220	            missingFields.add("lastName");
221	        }
222	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
223	            missingFields.add("address");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
226	            missingFields.add("city");
227	        }
228	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
229	            missingFields.add("telephone");
230	        }
231	        if (!missingFields.isEmpty()) {
232	            throw new MissingOwnerFieldsException(missingFields);
233	        }
234	    }
235	
236	    /**
237	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
238	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
239	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
240	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
241	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
242	     * whose {@code errors} array lists {@code postcode}.
243	     *
244	     * @param postcode the submitted postcode, or {@code null} when none was supplied
245	     * @param city the owner's city, whose region determines the acceptable postcode range
246	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
247	     */
248	    private void validatePostcode(String postcode, String city) {
249	        if (!StringUtils.hasText(postcode)) {
250	            return;
251	        }
252	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
253	            throw new InvalidOwnerFieldsException(List.of("postcode"));
254	        }
255	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
256	            throw new InvalidOwnerFieldsException(List.of("postcode"));
257	        }
258	    }
259	
260	    /**
261	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches an existing owner's.
262	     * All duplicate detection is consolidated into this single key, so a collision is reported to the
263	     * client as a 409 Conflict regardless of which field(s) coincide. Because the telephone is part of
264	     * the key, two owners that differ in telephone can never collide even when they share every other
265	     * component (for example two members of the same household).
266	     *
267	     * @param identityKey the derived identity key of the owner about to be created
268	     */
269	    private void rejectDuplicateOwner(String identityKey) {
270	        boolean duplicate = this.clinicService.findAllOwners().stream()
271	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
272	        if (duplicate) {
273	            throw new DuplicateOwnerIdentityException(identityKey);
274	        }
275	    }
276	
277	    /**
278	     * Derives the owner's {@code identityKey}, the single value through which all duplicate detection is
279	     * expressed. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
280	     * where the telephone and email have already been normalized. The household segment carries the
281	     * owner's {@code householdId} only when the owner knowingly belongs to a shared household (the
282	     * request opted in with {@code sharesHousehold}); otherwise it is empty, so an owner is identified
283	     * by telephone and email alone.
284	     *
285	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
286	     * @param sharesHousehold whether the request opted into a shared household
287	     * @return the derived identity key
288	     */
289	    private String buildIdentityKey(Owner owner, boolean sharesHousehold) {
290	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
291	        String household = sharesHousehold ? owner.getHouseholdId() : "";
292	        return owner.getTelephone() + "|" + email + "|" + household;
293	    }
294	
295	    /**
296	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
297	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
298	     * address; the accepted value is lower-cased before it is stored and returned.
299	     *
300	     * @param email the raw email value submitted by the client, or {@code null}
301	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
302	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
303	     */
304	    private String normalizeEmail(String email) {
305	        if (!StringUtils.hasText(email)) {
306	            return email;
307	        }
308	        if (!EMAIL_PATTERN.matcher(email).matches()) {
309	            throw new InvalidOwnerFieldsException(List.of("email"));
310	        }
311	        return email.toLowerCase();
312	    }
313	
314	    /**
315	     * Assigns the owner's customer code. The per-city sequence - one more than the number of owners
316	     * already in the owner's city - is drawn from stored state here, and the code itself is composed
317	     * by {@link CustomerCode}.
318	     *
319	     * @param owner the normalized owner about to be created
320	     * @return the assigned customer code
321	     */
322	    private String buildCustomerCode(Owner owner) {
323	        int sequence = (int) countOwnersInCity(owner.getCity()) + 1;
324	        return CustomerCode.forSequence(owner.getCity(), owner.getLastName(), sequence);
325	    }
326	
327	    /**
328	     * Counts how many owners already exist that share the supplied first and last name, compared
329	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
330	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
331	     *
332	     * @param firstName the submitted owner's first name
333	     * @param lastName the submitted owner's last name
334	     * @return the number of existing owners with the same first and last name, ignoring case
335	     */
336	    private int countNamesakes(String firstName, String lastName) {
337	        return (int) this.clinicService.findAllOwners().stream()
338	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
339	                && lastName.equalsIgnoreCase(existing.getLastName()))
340	            .count();
341	    }
342	
343	    /**
344	     * Counts how many existing owners already belong to the supplied household, identified by its
345	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
346	     * owner is added (this count plus one).
347	     *
348	     * @param householdId the normalized household identifier of the owner being created
349	     * @return the number of existing owners already sharing that {@code householdId}
350	     */
351	    private int countHouseholdMembers(String householdId) {
352	        return (int) this.clinicService.findAllOwners().stream()
353	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
354	            .count();
355	    }
356	
357	    /**
358	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
359	     * enforce the per-city capacity limit when a new owner is created.
360	     *
361	     * @param city the submitted owner's city
362	     * @return the number of existing owners in that city, ignoring case
363	     */
364	    private long countOwnersInCity(String city) {
365	        return this.clinicService.findAllOwners().stream()
366	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
367	            .count();
368	    }
369	
370	    /**
371	     * Counts how many owners have already been created on the supplied registration date. Used to
372	     * enforce the per-day capacity limit when a new owner is created.
373	     *
374	     * @param registrationDate the registration date of the owner being created
375	     * @return the number of existing owners already registered on that date
376	     */
377	    /**
378	     * Rolls a registration date forward to a business day. A registration date must fall on a
379	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
380	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
381	     * from the registration date (such as the membership number's year segment) and the daily
382	     * create-limit therefore use the adjusted date.
383	     *
384	     * @param date the effective registration date, whether supplied or defaulted to the server date
385	     * @return the same date when it is a weekday, otherwise the next Monday
386	     */
387	    private LocalDate toBusinessDay(LocalDate date) {
388	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
389	            date = date.plusDays(1);
390	        }
391	        return date;
392	    }
393	
394	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
395	        return this.clinicService.findAllOwners().stream()
