3	/**
4	 * Computes a single Luhn check digit (0 to 9) over the digits contained in a
5	 * string. Kept as a plain static helper - rather than a method on
6	 * {@link OwnerMapper} - so MapStruct does not mistake it for an implicit
7	 * property mapping.
8	 *
9	 * <p>Non-digit characters are ignored, so the digit is derived only from the
10	 * numeric characters of the input (for example the sequence digits of an
11	 * owner's customer code).
12	 */
13	public final class LuhnCheckDigit {
14	
15	    private LuhnCheckDigit() {
16	    }
17	
18	    /**
19	     * Computes the Luhn check digit over the digits contained in {@code s}.
20	     * The rightmost digit is doubled, alternating leftwards; each doubled
21	     * value over 9 has 9 subtracted; the check digit is the amount that brings
22	     * the running sum up to the next multiple of ten.
23	     *
24	     * @param s the string whose digits the check digit is computed over
25	     * @return the Luhn check digit, between 0 and 9 inclusive
26	     */
27	    public static int forDigits(String s) {
28	        int sum = 0;
29	        boolean dbl = true;
30	        for (int i = s.length() - 1; i >= 0; i--) {
31	            char c = s.charAt(i);
32	            if (c < '0' || c > '9') {
33	                continue;
34	            }
35	            int d = c - '0';
36	            if (dbl) {
37	                d *= 2;
38	                if (d > 9) {
39	                    d -= 9;
40	                }
41	            }
42	            sum += d;
43	            dbl = !dbl;
44	        }
45	        return (10 - (sum % 10)) % 10;
46	    }
47	
48	}
