6	 * Derives an owner's numeric membership level (1 to 3) from the state captured
7	 * when the owner was created. Kept as a plain static helper - rather than a
8	 * method on {@link OwnerMapper} - so MapStruct does not mistake it for an
9	 * implicit property mapping.
10	 *
11	 * <p>The level starts at 1, gains 1 when an email address is present, gains a
12	 * further 1 when the name was unique on create ({@code namesakeCount} is 0), and
13	 * is capped at 3. Level 4 is reserved for tenure and is never assigned here.
14	 */
15	public final class MembershipLevel {
16	
17	    /** The lowest membership level, assigned to every owner. */
18	    private static final int BASE_LEVEL = 1;
19	
20	    /** The highest level assignable on creation; level 4 is reserved for tenure. */
21	    private static final int MAX_LEVEL = 3;
22	
23	    private MembershipLevel() {
24	    }
25	
26	    /**
27	     * Computes the owner's membership level: 1, plus 1 when an email address is
28	     * present, plus 1 when {@code namesakeCount} is 0, capped at {@link #MAX_LEVEL}.
29	     *
30	     * @param owner the owner whose level to derive
31	     * @return the numeric membership level between 1 and 3 inclusive
32	     */
33	    public static int forOwner(Owner owner) {
34	        int level = BASE_LEVEL;
35	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
36	            level++;
37	        }
38	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
39	            level++;
40	        }
41	        return Math.min(level, MAX_LEVEL);
42	    }
43	
44	}
